const uploaded=$input.first();
const meta=JSON.parse(uploaded.json.body?.metadata||'{}');
if (!uploaded.binary?.document || !/^[a-f0-9]{32}$/.test(meta.web_job_id||'')) throw new Error('Document ou identifiant absent.');
const modes={auto:'Analyse automatique : local puis PISTE si nécessaire',local:'Pré-analyse locale des faits + textes officiels',full:'Revue du PDF + lois + annexe images',reading:'Lecture OCR + images - test sans API'};
const formats={cards:'Visuelle et simple - cartes (recommandée)',table:'Tableau d’audit - détaillé'};
if (!modes[meta.mode] || !formats[meta.format] || !['vision','ocr'].includes(meta.vision) || !['none','rerv'].includes(meta.technical)) throw new Error('Paramètres inconnus.');
const clean=v=>String(v||'').trim();
const mapped={json:{web_job_id:meta.web_job_id,origine_depot:'interface_web',
'Mode d’analyse':modes[meta.mode],'Lecture visuelle':meta.vision==='ocr'?'OCR seul':'OCR + Ministral vision',
'Pages visuelles à lire (facultatif)':clean(meta.pages),'Date de référence (AAAA-MM-JJ)':clean(meta.reference),'Commune(s) du projet':clean(meta.city),
'Présentation du rapport':formats[meta.format],'Département / région (facultatif)':clean(meta.region),
'Périmètre ou lot à contrôler':clean(meta.scope),'Pièces ou règles locales à vérifier (facultatif)':clean(meta.local_rules),
'Référentiel technique optionnel':meta.technical==='rerv'?'RER-V avril 2021 - comparaison technique optionnelle':'Aucun - revue nationale et pièces locales à vérifier',
'Citation justifiant la référence RER-V (facultatif)':clean(meta.rerv_quote)},
binary:{Document_PDF_ou_image:{...uploaded.binary.document,fileName:clean(meta.filename)||uploaded.binary.document.fileName}}};
return (( $input )=>{const item=$input.first();
const form={...item.json};
const clean=v=>String(v??'').trim();
const binaries=Object.entries(item.binary??{});
if(binaries.length!==1)throw new Error('Un seul PDF ou une seule image est attendu.');
const file=binaries[0][1];
if(!/\.(pdf|png|jpe?g)$/i.test(file.fileName??''))throw new Error('Format non pris en charge : PDF, PNG ou JPEG attendu.');
const date=clean(form['Date de référence (AAAA-MM-JJ)']);
const epoch=Date.parse(date+'T12:00:00Z');
if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(epoch)||new Date(epoch).toISOString().slice(0,10)!==date)throw new Error('Date réelle obligatoire au format AAAA-MM-JJ.');
const city=clean(form['Commune(s) du projet']);
if(city.length<2||city.length>300)throw new Error('Commune obligatoire (2 à 300 caractères).');
const allowed={
 'Mode d’analyse':['Analyse automatique : local puis PISTE si nécessaire','Pré-analyse locale des faits + textes officiels','Revue du PDF + lois + annexe images','Lecture OCR + images - test sans API'],
 'Lecture visuelle':['OCR + Ministral vision','OCR seul'],
 'Présentation du rapport':['Visuelle et simple - cartes (recommandée)','Tableau d’audit - détaillé'],
 'Référentiel technique optionnel':['Aucun - revue nationale et pièces locales à vérifier','RER-V avril 2021 - comparaison technique optionnelle']
};
for(const [key,values] of Object.entries(allowed))if(!values.includes(form[key]))throw new Error('Choix inconnu : '+key);
form['Date de référence (AAAA-MM-JJ)']=date;
form['Commune(s) du projet']=city;
form['Document PDF ou image']={filename:file.fileName};
return [{json:form,binary:{Document_PDF_ou_image:file}}];})({first:()=>mapped});

